function normalizeDomain(url) {
  if (!url) return "";
  let d = String(url).toLowerCase().trim();
  d = d.replace(/^https?:\/\//, "")
       .replace(/^www\./, "")
       .split(/[\/?#]/)[0]
       .trim();
  if (!d || !d.includes(".")) return "";
  const generiques = ["linkedin.com", "facebook.com", "pagesjaunes.fr", "societe.com", "indeed.com", "google.com", "hellowork.com"];
  if (generiques.some(g => d === g || d.endsWith("." + g))) return "";
  return d;
}

// --- Parsing de la réponse Claude (inchangé) ---
const content = $input.first().json.content;
const textBlocks = content.filter(c => c.type === 'text');
const allText = textBlocks.map(b => b.text).join(' ');

const cleaned = allText.replace(/```json/g, '').replace(/```/g, '');
const match = cleaned.match(/\{[^{}]*"pertinent"[^{}]*\}/);

const original = $('Loop Over Items3').last().json;

let result = { pertinent: false, raison: 'parse_error', secteur: 'NOT_FOUND', score: 0, classification: 'OUT' };
if (match) {
  try {
    result = JSON.parse(match[0]);
  } catch (e) {}
}

// Fallback : si tronqué mais classification visible dans le texte
if (result.raison === 'parse_error') {
  if (allText.includes('Classification → OUT') || allText.includes('classification": "OUT"')) {
    result = { pertinent: false, raison: 'ETT_concurrente', secteur: 'NOT_FOUND', score: 0, classification: 'OUT' };
  }
}

// --- Vérification : domaine déjà dans le Pipeline ---
// ⚠️ Le site web vient d'abord de la réponse Claude (result.site_web)
const siteItem = normalizeDomain(
  result.site_web || result.siteWeb || result.domaine ||
  original.domaine || original.site_web || original.siteWeb || original.website || ''
);

if (siteItem) {
  const pipelineRows = $('Lire Pipeline').all();
  for (const row of pipelineRows) {
    const sitePipeline = normalizeDomain(row.json.Domaine || '');
    if (sitePipeline && sitePipeline === siteItem) {
      result = {
        ...result,
        pertinent: false,
        raison: 'site_web_deja_existant',
        classification: 'OUT',
        score: 0
      };
      break;
    }
  }
}

return [{
  json: {
    ...original,
    ...result,
    _domaine: siteItem
  }
}];

