function normalizeCompany(name) {
  if (!name) return "";
  return name
    .toLowerCase()
    .replace(/\s+(sas|sarl|sa|sasu|eurl|sci|scop|eti|group|groupe)\b/g, "")
    .replace(/[^a-z0-9àâäéèêëïîôùûüÿçœæ]/g, "")
    .trim();
}
// --- Charger pipeline + rejetés + concurrents ---
const pipelineRows = $('Lire Pipeline').all();
const rejeteRows = $('Lire rejetés1').all();
const concurrentRows = $('Lire Concurrents').all();
const existingCompanies = new Set();
for (const row of pipelineRows) {
  const norm = normalizeCompany(row.json.Entreprise || '');
  if (norm) existingCompanies.add(norm);
}
for (const row of rejeteRows) {
  const norm = normalizeCompany(row.json.Company || '');
  if (norm) existingCompanies.add(norm);
}
for (const row of concurrentRows) {
  const norm = normalizeCompany(row.json.Entreprise || '');
  if (norm) existingCompanies.add(norm);
}
function isExisting(normName) {
  if (!normName) return false;
  if (existingCompanies.has(normName)) return true;
  for (const existing of existingCompanies) {
    if (normName.indexOf(existing) !== -1 || existing.indexOf(normName) !== -1) return true;
  }
  return false;
}
// --- Traitement des offres ---
const allOffres = $input.all();
if (!allOffres.length) {
  throw new Error("Aucun item en entrée");
}
const seenIds = new Set();
const seenEntreprises = new Set();
const results = [];
for (const o of allOffres) {
  // Dédup par ID
  const offreId = o.json.id || o.json.identifiant || o.json.urlOffre || '';
  if (offreId) {
    if (seenIds.has(offreId)) continue;
    seenIds.add(offreId);
  }
  // Dédup par entreprise
  const nom = o.json.entreprise || o.json.company_name || o.json.Entreprise || '';
  const norm = normalizeCompany(nom);
  if (norm) {
    if (seenEntreprises.has(norm)) continue;
    seenEntreprises.add(norm);
    // Skip si déjà dans pipeline/rejetés/concurrents
    if (isExisting(norm)) continue;
  }
  // Entreprise vide = on skip (pas exploitable pour la prospection)
  if (!norm) continue;
  results.push({
    json: {
      id: o.json.id || '',
      intitule: o.json.intitule || '',
      entreprise: nom,
      typeContrat: o.json.typeContrat || '',
      lieu: o.json.lieu || '',
      codePostal: o.json.codePostal || '',
      salaire: o.json.salaire || '',
      description: o.json.description || '',
      experience: o.json.experience || '',
      nombrePostes: o.json.nombrePostes || '',
      romeCode: o.json.romeCode || '',
      romeLibelle: o.json.romeLibelle || '',
      dateCreation: o.json.dateCreation || '',
      urlOffre: o.json.urlOffre || '',
      motsCles: o.json.motsCles || '',
      _date_check: new Date().toISOString().split('T')[0]
    }
  });
}
if (!results.length) {
  return [];
}
return results;

